@Composable
fun DailyGlowNavigationBar(selected: String, onSelect: (String) -> Unit) {
    Row(
        modifier = Modifier.fillMaxWidth().background(LifePaper).padding(horizontal = 10.dp, vertical = 8.dp),
        horizontalArrangement = Arrangement.SpaceEvenly,
        verticalAlignment = Alignment.CenterVertically
    ) {
        listOf("today" to "今日", "training" to "训练", "life" to "生活").forEach { (key, label) ->
            val active = selected == key
            Text(
                text = (if (active) "● " else "") + label,
                modifier = Modifier.clickable { onSelect(key) }.padding(horizontal = 14.dp, vertical = 8.dp),
                color = if (active) LifeBlue else LifeInk.copy(alpha = .72f),
                fontWeight = if (active) FontWeight.Bold else FontWeight.Normal,
                fontSize = 14.sp
            )
        }
    }
}

@Composable
fun TodayLandingScreen(trainingTitle: String, completed: Int, onTraining: () -> Unit, onLife: () -> Unit, context: Context) {
    val prefs = remember(context) { context.getSharedPreferences("dailyglow_life", Context.MODE_PRIVATE) }
    val date = LocalDate.now().toString()
    val water = remember(date) { prefs.getInt("water_$date", 0) }
    LazyColumn(
        modifier = Modifier.fillMaxSize().background(LifePaper),
        contentPadding = PaddingValues(18.dp),
        verticalArrangement = Arrangement.spacedBy(14.dp)
    ) {
        item {
            Text("今日", color = LifeBlue, fontSize = 28.sp, fontWeight = FontWeight.Bold)
            Text(LocalDate.now().toString(), color = LifeInk.copy(alpha = .72f), fontSize = 14.sp)
        }
        item { LifeCardBlock("今日训练", trainingTitle.ifBlank { "今日训练计划" }, "已完成 $completed 项", "开始训练", LifePeach, onTraining) }
        item { LifeCardBlock("生活记录", "喝水 $water / 8 杯 · 日记 · 衣橱 · 流水", "拾光小队与朋友们陪伴共用记录", "打开生活区", LifeSage, onLife) }
        item { Text("记录按日期保存在这台设备上。", color = LifeInk.copy(alpha = .68f), fontSize = 13.sp) }
    }
}

@Composable
private fun LifeCardBlock(title: String, body: String, foot: String, action: String, tint: Color, onClick: () -> Unit) {
    Card(
        modifier = Modifier.fillMaxWidth().clickable(onClick = onClick),
        shape = RoundedCornerShape(24.dp),
        colors = CardDefaults.cardColors(containerColor = tint.copy(alpha = .72f))
    ) {
        Column(Modifier.padding(18.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
            Text(title, color = LifeBlue, fontWeight = FontWeight.Bold, fontSize = 19.sp)
            Text(body, color = LifeInk, fontSize = 16.sp)
            Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.SpaceBetween, modifier = Modifier.fillMaxWidth()) {
                Text(foot, color = LifeInk.copy(alpha = .72f), fontSize = 12.sp)
                Text(action + "  ›", color = LifeBlue, fontWeight = FontWeight.SemiBold, fontSize = 14.sp)
            }
        }
    }
}

@Composable
fun DailyLifeHub(context: Context, onExit: () -> Unit = {}) {
    val prefs = remember(context) { context.getSharedPreferences("dailyglow_life", Context.MODE_PRIVATE) }
    var selectedDate by remember { mutableStateOf(LocalDate.now()) }
    val date = selectedDate.toString()
    val isToday = selectedDate == LocalDate.now()
    var section by remember { mutableStateOf("home") }
    var companion by remember { mutableStateOf(prefs.getString("companion", "拾光小队") ?: "拾光小队") }
    var water by remember(date) { mutableIntStateOf(prefs.getInt("water_$date", 0)) }
    var diary by remember(date) { mutableStateOf(prefs.getString("diary_$date", "") ?: "") }
    var outfit by remember(date) { mutableStateOf(prefs.getString("outfit_$date", "") ?: "") }
    var outfitStyle by remember(date) { mutableStateOf(prefs.getString("outfit_style_$date", "日常") ?: "日常") }
    var closet by remember { mutableStateOf(prefs.getString("closet_items", "") ?: "") }
    var mood by remember(date) { mutableStateOf(prefs.getString("mood_$date", "") ?: "") }
    var expenseSource by remember { mutableStateOf("支付宝") }
    var expenseCategory by remember { mutableStateOf("") }
    var amount by remember { mutableStateOf("") }
    var note by remember { mutableStateOf("") }
    var transactions by remember(date) { mutableStateOf(prefs.getString("transactions_$date", "") ?: "") }
    var saved by remember { mutableStateOf(false) }
    var ocrText by remember { mutableStateOf("") }
    var ocrStatus by remember { mutableStateOf("") }

    val receiptPicker = rememberLauncherForActivityResult(PickVisualMedia()) { uri ->
        if (uri == null) return@rememberLauncherForActivityResult
        ocrText = ""
        ocrStatus = "正在本机识别截图…"
        try {
            val image = InputImage.fromFilePath(context, uri)
            val recognizer = TextRecognition.getClient(ChineseTextRecognizerOptions.Builder().build())
            recognizer.process(image)
                .addOnSuccessListener { result ->
                    ocrText = result.text
                    val candidates = ocrAmountCandidates(result.text)
                    if (candidates.size == 1) {
                        amount = String.format(Locale.US, "%.2f", candidates.single())
                        ocrStatus = "识别完成，请核对金额、账户和分类后再保存。"
                    } else {
                        ocrStatus = if (result.text.isBlank()) "没有识别出文字，请换一张清晰截图。" else "已提取截图文字；金额不唯一，请核对后手动填写。"
                    }
                    recognizer.close()
                }
                .addOnFailureListener {
                    ocrStatus = "截图识别失败，请手动填写流水。"
                    recognizer.close()
                }
        } catch (_: Exception) {
            ocrStatus = "无法读取这张截图，请重新选择或手动填写。"
        }
    }

    val monthPrefix = "transactions_${selectedDate.year}-${selectedDate.monthValue.toString().padStart(2, '0')}"
    val monthLines = prefs.all
        .filterKeys { it.startsWith(monthPrefix) }
        .values.filterIsInstance<String>()
        .flatMap { it.lines() }
        .filter { it.isNotBlank() }
    val monthlyTotal = monthLines.sumOf { row ->
        Regex("¥([0-9]+(?:\\.[0-9]+)?)").find(row)?.groupValues?.getOrNull(1)?.toDoubleOrNull() ?: 0.0
    }
    val categoryTotals = monthLines.groupBy { it.split("·").getOrNull(1)?.trim()?.takeIf(String::isNotBlank) ?: "未分类" }
        .mapValues { (_, rows) -> rows.sumOf { Regex("¥([0-9]+(?:\\.[0-9]+)?)").find(it)?.groupValues?.getOrNull(1)?.toDoubleOrNull() ?: 0.0 } }
        .toList().sortedByDescending { it.second }

    Column(Modifier.fillMaxSize().background(LifePaper)) {
        LazyColumn(
            modifier = Modifier.weight(1f),
            contentPadding = PaddingValues(horizontal = 16.dp, vertical = 10.dp),
            verticalArrangement = Arrangement.spacedBy(10.dp)
        ) {
            item {
                LifeHero(section, onExit)
            }
            item {
                LifeDateStrip(
                    selectedDate = selectedDate,
                    isToday = isToday,
                    onPrevious = { selectedDate = selectedDate.minusDays(1) },
                    onNext = { if (!isToday) selectedDate = selectedDate.plusDays(1) }
                )
            }

            when (section) {
                "home" -> {
                    item { LifeNote("今天也给自己留一点空白。", "拾光小队陪你，把日子过得松弛又认真。", LifePeach) }
                    item { LifeSectionTitle("今天想记录什么？") }
                    item { LifeMenuCard("生活邮局", "写一封给今天的信，记下此刻心情", "写日记", "diary", LifeCard) { section = it } }
                    item { LifeMenuCard("衣橱裁缝铺", "记录今日穿搭，慢慢整理自己的衣橱", "记穿搭", "wardrobe", LifePeach) { section = it } }
                    item { LifeMenuCard("每日流水", "看本月收支，也可以导入账单截图", "记一笔", "ledger", LifeSage) { section = it } }
                    item { LifeMenuCard("今日小确幸", "喝水、三餐和生活习惯", "打开记录", "water", Color(0xFFE6EEF1)) { section = it } }
                    item { Text("本机保存 · 不会自动上传", Modifier.fillMaxWidth().padding(vertical = 8.dp), color = LifeInk.copy(alpha = .66f), fontSize = 12.sp, textAlign = TextAlign.Center) }
                }
                "diary" -> {
                    item { LifeNote("给今天的我：", "不管认真努力的时刻，还是偶尔发呆的片刻，都值得被温柔记住。", LifePeach) }
                    item {
                        LifePaperCard {
                            Text("写给今天的信", color = LifeBlue, fontSize = 19.sp, fontWeight = FontWeight.Bold)
                            OutlinedTextField(
                                value = diary,
                                onValueChange = { diary = it; saved = false },
                                modifier = Modifier.fillMaxWidth().height(190.dp),
                                label = { Text("亲爱的自己……") },
                                placeholder = { Text("把今天想说的话，慢慢写下来") }
                            )
                            Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.End) {
                                Button(onClick = { prefs.edit().putString("diary_$date", diary).apply(); saved = true }, colors = ButtonDefaults.buttonColors(containerColor = LifePeach)) {
                                    Text(if (saved) "已收好这封信" else "收好这封信", color = LifeBlue)
                                }
                            }
                        }
                    }
                    item {
                        LifePaperCard {
                            LifeSectionTitle("此刻的心情")
                            Row(horizontalArrangement = Arrangement.spacedBy(6.dp)) {
                                listOf("开心", "平静", "充实", "放松", "有点累").forEachIndexed { index, label ->
                                    val tint = listOf(LifePeach, Color(0xFFDCEAF0), Color(0xFFF4E2CE), LifeSage, Color(0xFFF2DAD6))[index]
                                    Text(
                                        label,
                                        Modifier.weight(1f).border(1.dp, if (mood == label) LifeBlue else tint, RoundedCornerShape(14.dp))
                                            .background(tint.copy(alpha = .45f), RoundedCornerShape(14.dp))
                                            .clickable { mood = label; prefs.edit().putString("mood_$date", label).apply() }
                                            .padding(vertical = 10.dp),
                                        color = LifeBlue, fontSize = 11.sp, textAlign = TextAlign.Center
                                    )
                                }
                            }
                        }
                    }
                    item {
                        LifePaperCard {
                            LifeSectionTitle("💧 喝点水吧")
                            Text("$water / 8 杯 · 约 ${water * 200} ml", color = LifeBlue, fontSize = 18.sp, fontWeight = FontWeight.SemiBold)
                            Button(onClick = { if (water < 8) water += 1; prefs.edit().putInt("water_$date", water).apply() }, colors = ButtonDefaults.buttonColors(containerColor = Color(0xFFDCEAF0))) {
                                Text("＋ 喝一杯水", color = LifeBlue)
                            }
                        }
                    }
                }
                "wardrobe" -> {
                    item { LifeNote("把喜欢的自己，穿进今天的生活里。", "搭配不用很复杂，舒服自在就是好看。", LifePeach) }
                    item {
                        Row(horizontalArrangement = Arrangement.spacedBy(6.dp)) {
                            listOf("日常", "校园", "运动", "亮眼").forEach { label ->
                                Text(label, Modifier.weight(1f).border(1.dp, if (outfitStyle == label) LifePeach else LifeCard, RoundedCornerShape(18.dp))
                                    .background(if (outfitStyle == label) LifePeach.copy(alpha = .55f) else LifeCard, RoundedCornerShape(18.dp))
                                    .clickable { outfitStyle = label; prefs.edit().putString("outfit_style_$date", label).apply() }
                                    .padding(vertical = 11.dp), color = LifeBlue, fontSize = 13.sp, textAlign = TextAlign.Center)
                            }
                        }
                    }
                    item {
                        LifePaperCard {
                            LifeSectionTitle("今天穿什么")
                            Text("今日风格 · $outfitStyle", color = LifeBlue.copy(alpha = .76f), fontSize = 13.sp)
                            OutlinedTextField(value = outfit, onValueChange = { outfit = it; saved = false }, modifier = Modifier.fillMaxWidth().height(120.dp), label = { Text("写下今天的搭配") }, placeholder = { Text("例如：针织开衫、牛仔裤、帆布鞋") })
                            Button(onClick = { prefs.edit().putString("outfit_$date", outfit).putString("outfit_style_$date", outfitStyle).apply(); saved = true }, colors = ButtonDefaults.buttonColors(containerColor = LifePeach)) {
                                Text(if (saved) "已保存今日穿搭" else "保存今日穿搭", color = LifeBlue)
                            }
                        }
                    }
                    item {
                        LifePaperCard {
                            Row(Modifier.fillMaxWidth(), verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.SpaceBetween) {
                                LifeSectionTitle("我的衣橱")
                                Text("＋ 添加衣服", Modifier.clickable { closet = (closet.trimEnd() + if (closet.isBlank()) "" else "\n") + "新衣物" }.padding(6.dp), color = LifeBlue, fontSize = 13.sp)
                            }
                            val categories = listOf("上衣", "下装", "连衣裙", "外套", "鞋子", "包包", "配饰")
                            Row(horizontalArrangement = Arrangement.spacedBy(5.dp)) {
                                categories.forEachIndexed { index, label ->
                                    Text("${listOf("♧", "▱", "♙", "♧", "⌁", "▢", "✦")[index]}\n$label", Modifier.weight(1f).background(listOf(Color(0xFFF7E5DC), Color(0xFFE2EDF0), LifeSage, Color(0xFFF7E5DC), Color(0xFFE2EDF0), LifeSage, Color(0xFFF7E5DC))[index], RoundedCornerShape(12.dp)).padding(vertical = 8.dp), color = LifeBlue, fontSize = 10.sp, textAlign = TextAlign.Center)
                                }
                            }
                            OutlinedTextField(value = closet, onValueChange = { closet = it; saved = false }, modifier = Modifier.fillMaxWidth().height(130.dp), label = { Text("衣物清单 · 每行一件") }, placeholder = { Text("开衫\n牛仔裤\n帆布鞋") })
                            Button(onClick = { prefs.edit().putString("closet_items", closet).apply(); saved = true }, colors = ButtonDefaults.buttonColors(containerColor = Color(0xFFDCEAF0))) {
                                Text(if (saved) "已保存衣橱" else "保存衣橱", color = LifeBlue)
                            }
                        }
                    }
                }
                "ledger" -> {
                    item { LifeNote("把收支理清，也是照顾未来的自己。", "农行、支付宝和微信流水都可以记在这里。", LifeSage) }
                    item {
                        LifePaperCard {
                            LifeSectionTitle("${selectedDate.year}年${selectedDate.monthValue}月 · 收支统计")
                            Text("本月支出", color = LifeBlue.copy(alpha = .78f), fontSize = 14.sp)
                            Text("¥${"%.2f".format(Locale.US, monthlyTotal)}", color = LifeBlue, fontSize = 30.sp, fontWeight = FontWeight.Bold)
                            Text("本机记录的支出合计", color = LifeInk.copy(alpha = .7f), fontSize = 12.sp)
                            if (categoryTotals.isEmpty()) Text("记录几笔后，这里会汇总消费分类。", color = LifeInk.copy(alpha = .7f), fontSize = 13.sp)
                            categoryTotals.take(4).forEach { (category, total) ->
                                Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) {
                                    Text(category, color = LifeInk, fontSize = 13.sp)
                                    Text("¥${"%.2f".format(Locale.US, total)}", color = LifeBlue, fontSize = 13.sp)
                                }
                                Box(Modifier.fillMaxWidth().height(7.dp).background(Color(0xFFE9E5DD), RoundedCornerShape(8.dp))) {
                                    Box(Modifier.fillMaxWidth(if (monthlyTotal > 0) (total / monthlyTotal).toFloat().coerceIn(.02f, 1f) else 0f).height(7.dp).background(LifePeach, RoundedCornerShape(8.dp)))
                                }
                            }
                        }
                    }
                    item {
                        LifePaperCard {
                            Row(Modifier.fillMaxWidth(), verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.SpaceBetween) {
                                LifeSectionTitle("最近流水")
                                Text("共 ${monthLines.size} 笔", color = LifeInk.copy(alpha = .7f), fontSize = 12.sp)
                            }
                            if (monthLines.isEmpty()) Text("还没有流水，记下今天的第一笔吧。", color = LifeInk.copy(alpha = .68f), fontSize = 13.sp)
                            monthLines.take(8).forEach { row ->
                                Row(Modifier.fillMaxWidth().padding(vertical = 5.dp), verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.SpaceBetween) {
                                    Column(Modifier.weight(1f)) {
                                        Text(row.split("·").getOrNull(1)?.trim()?.ifBlank { "日常支出" } ?: "日常支出", color = LifeBlue, fontWeight = FontWeight.SemiBold, fontSize = 14.sp)
                                        Text(row.take(48), color = LifeInk.copy(alpha = .7f), fontSize = 11.sp)
                                    }
                                    Text(Regex("¥[0-9]+(?:\\.[0-9]+)?").find(row)?.value ?: "", color = LifeBlue, fontWeight = FontWeight.Bold, fontSize = 14.sp)
                                }
                            }
                        }
                    }
                    item {
                        LifePaperCard {
                            Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                                Button(onClick = { section = "add_expense" }, modifier = Modifier.weight(1f), colors = ButtonDefaults.buttonColors(containerColor = LifePeach)) { Text("✎ 记一笔", color = LifeBlue) }
                                Button(onClick = { receiptPicker.launch(PickVisualMediaRequest(PickVisualMedia.ImageOnly)); section = "add_expense" }, modifier = Modifier.weight(1f), colors = ButtonDefaults.buttonColors(containerColor = Color(0xFFDCEAF0))) { Text("▣ 导入账单截图", color = LifeBlue, fontSize = 12.sp) }
                            }
                            Text("选择图片后先预览识别结果，核对后再保存。", color = LifeInk.copy(alpha = .68f), fontSize = 11.sp)
                        }
                    }
                }
                "add_expense" -> {
                    item {
                        LifePaperCard {
                            LifeSectionTitle("记一笔流水")
                            Button(onClick = { receiptPicker.launch(PickVisualMediaRequest(PickVisualMedia.ImageOnly)) }, colors = ButtonDefaults.buttonColors(containerColor = Color(0xFFDCEAF0))) { Text("▣ 选择账单截图", color = LifeBlue) }
                            if (ocrStatus.isNotBlank()) {
                                Text(ocrStatus, color = LifeBlue, fontWeight = FontWeight.SemiBold, fontSize = 13.sp)
                                if (ocrText.isNotBlank()) Text(ocrText.take(1000), color = LifeInk, fontSize = 12.sp, lineHeight = 18.sp)
                                Text("截图只在本机识别，不会保存原图。", color = LifeInk.copy(alpha = .7f), fontSize = 11.sp)
                            }
                            Row(horizontalArrangement = Arrangement.spacedBy(6.dp)) {
                                listOf("农行", "支付宝", "微信").forEach { source ->
                                    Button(onClick = { expenseSource = source }, contentPadding = PaddingValues(horizontal = 10.dp, vertical = 7.dp), colors = ButtonDefaults.buttonColors(containerColor = if (expenseSource == source) LifePeach else LifeSage)) { Text(source, color = LifeBlue, fontSize = 12.sp) }
                                }
                            }
                            OutlinedTextField(value = amount, onValueChange = { amount = it; saved = false }, modifier = Modifier.fillMaxWidth(), label = { Text("金额（元）") }, keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Decimal))
                            OutlinedTextField(value = expenseCategory, onValueChange = { expenseCategory = it; saved = false }, modifier = Modifier.fillMaxWidth(), label = { Text("消费分类") })
                            OutlinedTextField(value = note, onValueChange = { note = it; saved = false }, modifier = Modifier.fillMaxWidth(), label = { Text("备注（可选）") })
                            Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                                Button(onClick = { section = "ledger" }, colors = ButtonDefaults.buttonColors(containerColor = LifeCard)) { Text("取消", color = LifeBlue) }
                                Button(onClick = {
                                    val value = amount.toDoubleOrNull()
                                    if (value != null && value > 0) {
                                        val newTransactions = listOfNotNull("$expenseSource · ${expenseCategory.ifBlank { "未分类" }} · $note  -¥${"%.2f".format(Locale.US, value)}", transactions.takeIf { it.isNotBlank() }).joinToString("\n")
                                        transactions = newTransactions
                                        prefs.edit().putString("transactions_$date", newTransactions).apply()
                                        amount = ""; note = ""; expenseCategory = ""; saved = true; section = "ledger"
                                    }
                                }, colors = ButtonDefaults.buttonColors(containerColor = LifePeach)) { Text(if (saved) "已保存" else "确认保存", color = LifeBlue) }
                            }
                        }
                    }
                }
                "water" -> {
                    item { LifeNote("小口喝水，也是在照顾自己呀。", "轻松记录今天的喝水、三餐和习惯。", Color(0xFFDCEAF0)) }
                    item {
                        LifePaperCard {
                            Text("💧  $water / 8 杯", color = LifeBlue, fontSize = 27.sp, fontWeight = FontWeight.Bold)
                            Row(horizontalArrangement = Arrangement.spacedBy(6.dp)) { (0 until 8).forEach { Text(if (it < water) "🥛" else "○", fontSize = 19.sp) } }
                            Button(onClick = { if (water < 8) water += 1; prefs.edit().putInt("water_$date", water).apply() }, colors = ButtonDefaults.buttonColors(containerColor = Color(0xFFDCEAF0))) { Text("＋ 喝一杯水", color = LifeBlue) }
                        }
                    }
                    item {
                        LifePaperCard {
                            LifeSectionTitle("三餐记录")
                            listOf("早餐", "午餐", "晚餐").forEach { meal ->
                                var mealText by remember(date, meal) { mutableStateOf(prefs.getString("meal_${meal}_$date", "") ?: "") }
                                OutlinedTextField(value = mealText, onValueChange = { mealText = it }, modifier = Modifier.fillMaxWidth(), label = { Text(meal) }, singleLine = true)
                                Button(onClick = { prefs.edit().putString("meal_${meal}_$date", mealText).apply(); saved = true }, colors = ButtonDefaults.buttonColors(containerColor = LifePeach)) { Text("保存$meal", color = LifeBlue) }
                            }
                            LifeSectionTitle("生活习惯")
                            listOf("今天活动过", "按时休息").forEachIndexed { index, label ->
                                val key = if (index == 0) "habit_move_$date" else "habit_sleep_$date"
                                var checked by remember(date, key) { mutableStateOf(prefs.getBoolean(key, false)) }
                                Text((if (checked) "☑ " else "□ ") + label, modifier = Modifier.clickable { checked = !checked; prefs.edit().putBoolean(key, checked).apply() }.padding(vertical = 6.dp), color = LifeInk, fontSize = 15.sp)
                            }
                        }
                    }
                }
                else -> {
                    item {
                        LifePaperCard {
                            LifeSectionTitle("拾光小队 · 陪你记录生活")
                            Text("当前陪伴：$companion", color = LifeInk, fontSize = 14.sp)
                            listOf("拾光小队", "朋友们陪伴").forEach { option ->
                                Button(onClick = { companion = option; prefs.edit().putString("companion", option).apply() }, colors = ButtonDefaults.buttonColors(containerColor = if (companion == option) LifePeach else LifeCard)) { Text(option, color = LifeBlue) }
                            }
                            Text("两种陪伴模式共用同一份日记、衣橱和流水记录。", color = LifeInk.copy(alpha = .7f), fontSize = 12.sp)
                            Button(onClick = onExit, colors = ButtonDefaults.buttonColors(containerColor = LifeSage)) { Text("返回 DailyGlow 今日", color = LifeBlue) }
                        }
                    }
                }
            }
            item { Spacer(Modifier.height(8.dp)) }
        }
        LifeBottomNavigation(section = section, onSelect = { section = it })
    }
}

@Composable
private fun LifeHero(section: String, onExit: () -> Unit) {
    val artValue = when (section) {
        "wardrobe" -> WardrobePreviewArt
        "ledger", "add_expense" -> LedgerPreviewArt
        else -> DiaryPreviewArt
    }
    val bitmap = remember(artValue) {
        val bytes = Base64.decode(artValue, Base64.DEFAULT)
        BitmapFactory.decodeByteArray(bytes, 0, bytes.size).asImageBitmap()
    }
    val title = when (section) {
        "diary" -> "生活邮局"
        "wardrobe" -> "衣橱裁缝铺"
        "ledger", "add_expense" -> "每日流水"
        "water" -> "今日小确幸"
        "profile" -> "拾光小队"
        else -> "今日生活"
    }
    val subtitle = when (section) {
        "diary" -> "写给今天的自己"
        "wardrobe" -> "穿上喜欢的生活"
        "ledger", "add_expense" -> "把日子记得清清楚楚"
        "water" -> "慢慢照顾自己"
        else -> "把日常轻轻收好"
    }
    Row(Modifier.fillMaxWidth().height(155.dp), verticalAlignment = Alignment.CenterVertically) {
        Column(Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(8.dp)) {
            Text(title, color = LifeBlue, fontSize = 22.sp, fontWeight = FontWeight.Bold)
            Text(subtitle, color = LifeInk.copy(alpha = .78f), fontSize = 12.sp, lineHeight = 18.sp)
            Text("‹ 返回 DailyGlow", Modifier.clickable(onClick = onExit).padding(top = 4.dp), color = LifeBlue.copy(alpha = .75f), fontSize = 11.sp)
        }
        Image(bitmap, contentDescription = title, modifier = Modifier.width(190.dp).height(145.dp), contentScale = ContentScale.Fit)
    }
}

@Composable
private fun LifeDateStrip(selectedDate: LocalDate, isToday: Boolean, onPrevious: () -> Unit, onNext: () -> Unit) {
    Row(
        Modifier.fillMaxWidth().background(LifeCard, RoundedCornerShape(14.dp)).border(1.dp, Color(0xFFF0E9E0), RoundedCornerShape(14.dp)).padding(horizontal = 10.dp, vertical = 10.dp),
        horizontalArrangement = Arrangement.SpaceBetween, verticalAlignment = Alignment.CenterVertically
    ) {
        Text("‹", Modifier.clickable(onClick = onPrevious).padding(horizontal = 8.dp), color = LifeBlue, fontSize = 22.sp)
        Text("${todayLabel(selectedDate)}  ·  ${selectedDate.dayOfWeek.name}", color = LifeBlue, fontSize = 14.sp)
        Text("›", Modifier.clickable(enabled = !isToday, onClick = onNext).padding(horizontal = 8.dp), color = if (isToday) LifeInk.copy(alpha = .3f) else LifeBlue, fontSize = 22.sp)
    }
}

