@Composable
private fun LifeBottomNavigation(section: String, onSelect: (String) -> Unit) {
    val selected = when (section) {
        "ledger", "add_expense", "wardrobe" -> "records"
        "diary", "water" -> "happiness"
        "profile" -> "me"
        else -> "today"
    }
    Row(Modifier.fillMaxWidth().background(LifeCard).padding(horizontal = 4.dp, vertical = 7.dp), horizontalArrangement = Arrangement.SpaceEvenly) {
        listOf("today" to "⌂\n今日", "records" to "▤\n记录", "happiness" to "❀\n小确幸", "me" to "♡\n我").forEach { (tab, label) ->
            Text(label, Modifier.weight(1f).clickable { onSelect(when(tab) { "today" -> "home"; "records" -> "ledger"; "happiness" -> "water"; else -> "profile" }) }.padding(vertical = 4.dp), color = if (selected == tab) LifeBlue else LifeInk.copy(alpha = .7f), fontSize = 12.sp, textAlign = TextAlign.Center, lineHeight = 17.sp)
        }
    }
}


private fun todayLabel(date: LocalDate): String = "${date.year}年${date.monthValue}月${date.dayOfMonth}日"

private fun ocrAmountCandidates(raw: String): List<Double> {
    val candidates = mutableListOf<Double>()
    raw.lineSequence().forEach { line ->
        val hasCurrencyMarker = line.contains("¥") || line.contains("￥") || line.contains("元")
        if (hasCurrencyMarker) {
            val tokens = line.replace("¥", " ").replace("￥", " ").replace("元", " ")
                .split(Regex("[^0-9.,+-]+"))
            tokens.mapNotNull { it.replace(",", ".").toDoubleOrNull() }
                .filter { it > 0.0 }
                .forEach { candidates.add(it) }
        }
    }
    return candidates.distinct()
}
